import{_ as o,c as a,o as e,ag as r}from"./chunks/framework._xRlcm3f.js";const p=JSON.parse('{"title":"掘金配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/custom-juejin.md","filePath":"platforms/custom-juejin.md","lastUpdated":1790228279000}'),d={name:"platforms/custom-juejin.md"};function i(l,t,n,s,c,h){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="掘金配置指南" tabindex="-1">掘金配置指南 <a class="header-anchor" href="#掘金配置指南" aria-label="Permalink to &quot;掘金配置指南&quot;">​</a></h1><p>通过 <strong>Cookie 授权</strong>发布到掘金。图片默认走掘金原生上传，默认使用 Markdown 发布。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>在浏览器登录掘金。</li><li>无需 API Token，只用 Cookie。</li><li>确认能打开掘金创作中心。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>默认 <code>https://juejin.cn</code>，一般不改</td></tr><tr><td>API 地址</td><td>默认 <code>https://api.juejin.cn</code>，一般不改</td></tr><tr><td>Cookie</td><td>点「1 去登录」登录后关闭窗口，再点「2 自动读取 Cookie」；也可展开「手动编辑」直接粘贴</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/post/[postid]</code></td></tr><tr><td>发布格式</td><td>默认 Markdown</td></tr><tr><td>分类</td><td>发布目标分类（如「后端」）；未选择回退默认分类「后端」</td></tr><tr><td>图床</td><td>默认「当前平台」（掘金原生直传）；也可选「不使用」或「PicGo 强烈推荐」</td></tr></tbody></table><blockquote><p>标签与摘要：掘金要求带标签与摘要，未显式设置时插件回退默认标签「程序员」与默认摘要。</p></blockquote><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「1 去登录」→ 登录掘金 → 关闭窗口 → 点「2 自动读取 Cookie」→ 验证。</li><li>快速发布 → 选掘金 → 发布。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>发布时报“必须选择一个分类/标签”或“摘要参数错误”</strong>：掘金要求分类、标签和摘要。未显式设置时插件会用默认分类“后端”、默认标签“程序员”与默认摘要；建议在文档里显式做好设置。</li><li><strong>Cookie 验证失败</strong>：确认浏览器已登录掘金并能打开创作中心，重新读取 Cookie。</li><li><strong>图片图床</strong>：默认「当前平台」，掘金使用平台原生直传。外链图片原样保留、不转存；不需要本机 PicGo 服务，需要时可改选「PicGo 强烈推荐」。</li><li><strong>文章一直“审核中”</strong>：掘金新文章初始处于审核（audit=1），需平台放行后（audit=2）才对外可见，与上传机制无关。</li></ul>',11)])])}const m=o(d,[["render",i]]);export{p as __pageData,m as default};
